module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both[i] = in[i] & in[i+1] for i = 0,1,2
    // out_both[3] is not needed (no left neighbour for in[3])
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = 1'b0;   // placeholder, not used per spec

    // out_any[i] = in[i] | in[i-1] for i = 1,2,3
    // out_any[0] is not needed (no right neighbour for in[0])
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];
    assign out_any[0] = 1'b0;   // placeholder, not used per spec

    // out_different[i] = in[i] ^ in[i-1] with wrap-around
    // i=3: neighbour is in[0]; i=2: neighbour is in[3]... wait, spec says:
    // "out_different[2] should indicate if in[2] is different from in[3]"
    // "treat the vector as wrapping around, so in[3]'s neighbour to the left is in[0]"
    // Therefore:
    //   out_different[3] = in[3] ^ in[0]
    //   out_different[2] = in[2] ^ in[3]
    //   out_different[1] = in[1] ^ in[2]
    //   out_different[0] = in[0] ^ in[1]  (neighbour to the left of in[0] is in[1] due to wrap)
    assign out_different[0] = in[0] ^ in[1];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[3] = in[3] ^ in[0];

endmodule

