module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 bytes of the current message
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-asserted

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        // Load first byte into shift register MSB
                        shift_reg <= {in, 16'b0};
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    // Shift in second byte (in) into bits [15:8]
                    shift_reg <= {shift_reg[23:8], in};
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    // Shift in third byte (in) into bits [7:0]
                    shift_reg <= {shift_reg[23:8], in};
                end

                BYTE3: begin
                    // All 3 bytes received
                    // Output the message and assert done in this cycle
                    out_bytes <= shift_reg;
                    done      <= 1'b1;
                    // Return to IDLE for next message
                    next_state <= IDLE;
                end
            endcase
        end
    end

endmodule

