module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD count value
);

    // Internal register for the BCD counter (16 bits)
    reg [15:0] count;

    // Assign the output ports
    assign q = count;

    // ena[0] is always 1 (ones digit always increments)
    // ena[1] enables tens digit increment
    // ena[2] enables hundreds digit increment
    // Note: thousands digit (q[15:12]) has no enable output per spec
    assign ena = {count[7:4] == 4'd9, count[11:8] == 4'd9, count[3:0] == 4'd9};

    // Synchronous always block triggered on positive edge of clk
    always @(posedge clk) begin
        if (reset) begin
            count <= 16'd0;
        end else begin
            // BCD increment logic
            if (count == 16'd9999) begin
                // Rollover to 0 when reaching 9999
                count <= 16'd0;
            end else if (count[3:0] == 4'd9) begin
                // If ones digit is 9, propagate carry to tens
                // and check tens, etc.
                if (count[7:4] == 4'd9) begin
                    if (count[11:8] == 4'd9) begin
                        // All three lower digits are 9, increment thousands
                        count <= count + 16'd1;
                    end else begin
                        // Increment hundreds, reset lower digits
                        count <= {count[15:12], count[11:8] + 1'b1, 4'd0, count[3:0]};
                    end
                end else begin
                    // Increment tens, reset ones
                    count <= {count[15:8], count[7:4] + 1'b1, 4'd0};
                end
            end else begin
                // Simple increment of ones digit
                count <= count + 16'd1;
            end
        end
    end

endmodule

