module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11
    reg [1:0] state, next_state;

    // Outputs
    assign f = (state == 2'b01);
    assign g = (state == 2'b11);

    // State register (synchronous reset, active low)
    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= 2'b00;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            2'b00: // State A
                next_state = 2'b01; // Go to B on deasserted reset
            2'b01: // State B
                if (x)
                    next_state = 2'b10; // x=1 -> C
                else
                    next_state = 2'b01; // stay B
            2'b10: // State C
                if (x)
                    next_state = 2'b11; // x=1 again -> D
                else
                    next_state = 2'b00; // reset on x=0
            2'b11: // State D
                if (y)
                    next_state = 2'b11; // y=1 -> stay D
                else if (!x) // Check for timeout: if x becomes 0 without y=1
                    next_state = 2'b00;
                else
                    next_state = 2'b11; // wait for y or x=0
        endcase
    end

endmodule

